output_path = "/home/ctfplayer/ctf_files/extracted/"

# Generate potential passwords
def generate_passwords():
    keywords = ["Tax", "Nov", "November", "tax", "nov", "november"]
    years = [str(year) for year in range(2000, 2025)]

    for keyword in keywords:
        # Combine keyword with different years
        for year in years:
            yield keyword + year

        # Yield just the keyword options as well
        yield keyword

    # Add some alphanumeric combinations just in case
    chars = string.ascii_letters + string.digits
    for length in range(6, 9):  # Adjust length range as needed
        for combo in itertools.product(chars, repeat=length):
            yield ''.join(combo)

